      "summary": "This report examines the implementation and use of Rajasthan's Mukhyamantri Chiranjeevi Swasthya Bima Yojana, distinguishing insurance enrolment from healthcare utilisation and financial protection. It combines Jaipur district administrative records with a survey of 15 families to investigate hospital preferences, awareness of entitlements, out-of-pocket expenditure and the social factors affecting healthcare decisions. The analysis considers differences in rural and urban experiences, continuing costs associated with treatment, and gendered inequalities in access to information and decision-making. It finds that formal insurance coverage does not necessarily displace established patterns of healthcare seeking or eliminate financial barriers to treatment.",
