      "summary": "This report analyses the trajectory and structure of Rajasthan's economy between 2011 and 2024 using official national and state economic statistics. It compares changes in gross state domestic product and gross state value added with national trends, and examines per-capita income and sectoral contributions to output. By considering year-on-year fluctuations alongside longer-term patterns, the analysis distinguishes aggregate economic expansion from changes in the composition of growth. The report situates Rajasthan's recent performance within its continuing dependence on agriculture and the uneven contribution of different sectors to economic activity.",
