          "type": "paragraph",
          "text": "Niti Aayog’s report on Harnessing Green Hydrogen highlights issues such as high costs, complex supply chains and regulatory issues in building a green hydrogen economy. Further, hydrogen can be produced via multiple ways and can be used in various industries, thus making its supply chain more intricate compared to oil and gas.",
