      "topics": [
        "Urban systems",
        "GIS",
        "Mobility & access"
      ],
      "summary": "This study assesses pedestrian accessibility and the spatial distribution of walkability in Jaipur through a combination of GIS analysis, field observation and urban mobility literature. Using QGIS, it maps 15-minute walking access to metro stations, bus stops and healthcare facilities, examines points of interest around transit stations, and compares intersection density with mapped accident hotspots. The analysis identifies gaps in transit coverage, including areas of the northern Walled City beyond a 15-minute walk of public transport, and finds that the identified accident-hotspot clusters occur in areas of very high intersection density. The findings support a more spatially targeted approach to pedestrian safety, last-mile connectivity and equitable access to everyday services.",
      "methods": [
        "QGIS",
        "Spatial analysis",
        "OpenStreetMap",
        "Field observation",
        "Policy analysis"
      ],
