      "id": "forest-cover",
      "title": "Balancing Act or Legal Loosening? A Look at the Misleading Metrics of India’s Forest Cover",
      "kind": "Research paper",
      "category": "Research papers",
      "year": "Coursework",
      "topics": [
        "Environment & regulation",
        "Legal analysis",
        "Measurement"
      ],
      "summary": "This paper examines the extent to which official estimates of India's forest cover capture ecological change. It reviews the Forest (Conservation) Act, successive Forest Survey of India measurement criteria and differences between administrative and satellite-based classifications. Particular attention is given to the reduction in minimum mapped area, the inclusion of plantations and trees outside recorded forests, and inconsistencies in the treatment of forest land across government institutions. The analysis argues that aggregate gains in reported forest cover cannot, in isolation, establish improvements in natural forest extent, biodiversity or conservation outcomes.",
      "methods": [
        "Documentary analysis",
        "Legal analysis",
        "Literature review"
      ],
