          "type": "paragraph",
          "text": "Additionally, the Act exempts land converted to non-forest use before the SC ruling (December 12, 1996) thus contradicting the judgement itself. This then suggests that any forest land where non-forest activities were authorised between October 25, 1980 and December 12, 1996 would be exempted. So non-forest activities on such land can bypass the FCA 1980’s approval process. The court rejected such utilization of forest land for non-forest purposes in cases like the “State of Bihar v. Banshi Ram Modi (1985).” The 2023 amendment also waives off approval for forest land use for border security projects within 100 kms of border and security infrastructure of under 10 hectares. This puts the densely forested areas of north-eastern states at risk of accelerated deforestation. Compensatory afforestation cannot replicate the rich diversity. Recently, the Supreme Court (2023) questioned the rationale of having zoos within tiger reserves and national parks, as the 2023 amendment exempts zoos from prior approval under the FCA 1980.",
