      "id": "crop-residue",
      "title": "Policy Memo for Crop Residue Management in Punjab and Haryana",
      "kind": "Policy memo",
      "category": "Policy & reports",
      "year": "M.A. coursework",
      "topics": [
        "Agriculture",
        "Environment & regulation",
        "Policy evaluation"
      ],
      "summary": "This policy memo evaluates crop-residue management in Punjab and Haryana, focusing on the institutional, agricultural and economic conditions that sustain stubble burning. It reviews existing mechanisation subsidies and state action plans, including differences in financial incentives and administrative implementation. The analysis compares the Pusa Decomposer and mulch-based Happy Seeder approaches against economic, environmental, financial, political, operational and social feasibility criteria. It recommends greater attention to the affordability and adoption of decomposition methods while acknowledging their dependence on cropping calendars, temperature and moisture conditions. The findings highlight the importance of aligning policy instruments with farmers' operational constraints.",
      "methods": [
        "Comparative policy analysis",
        "Feasibility assessment"
      ],
      "note": "Original research document included.",
