          "text": "Crop residue burning adds significant emissions load to our already existing choked cities. When 1 tonne of crop residue is burnt on field, it releases approximately 1400kg of ,58 CO2 kg of CO,11kg of particulate matter (PM),4.9kg of NOx and 1.2 kg of SO2.Due to such high amount of emissions crop residue burning has become a major problem in India. A report from the System of Air Quality and Weather Forecasting and Research (SAFAR) found that in 2019, crop burning made up about 10-20% of the air pollution in Delhi and nearby areas during October and November. On some days when a lot of burning happened, it was as high as 44%. During this time, the air in Delhi was 12-20 times worse than what the World Health Organization says is safe. Not only does this burning create more pollution and smog, but it also hurts nature by reducing biodiversity, harming farmland, and making the soil less fertile.",
