          "type": "paragraph",
          "text": "Current Action Plan of Punjab: As we all know; Punjab’s major crops are rice and wheat; which are the major crops that cause stubble burning. To address this issue, the government of Punjab has come out with a notice in 2022 namely “Action Plan for Control of Burning of Crop Residue in the State of Punjab” which is still being widely followed. The Action Plan calls for various Central and State incentivization programs to stop stubble burning. Various government officials have been directed to take severe action against stubble burners under section 19(5) of the Air (Prevention and Control of Pollution) Act, 1981. Many initiatives by the State and the Central Departments to eradicate stubble burning. A few of them are: -",
