          "text": "Alternative 2: To roll out an immediate plan to arrest the stubble-burning issue, the use method of “Mulch and Happy Seeder” seems as a viable option. It entails a two-fold process of straw and stubble management and seeding. A layer of undecomposed material is applied to the surface of the soil and then the Happy Seeder shreds the straws and seeds wheat simultaneously. With the help of large-scale government subsidies and awareness amongst the farmers, over 5,000 hectares of land were using the Happy Seeder and the projected growth of this method is estimated to be around 700,000 by 2025. This alternative helps in the improvement of the soil condition, moisture, and texture and reduces weed growth.  However, the fallback in this method is the high cost of the tractor and the ongoing variable cost to operate the Happy Seeder. It has one of the lowest CO2 outputs about 0.93 tonnes per hectare.",
