      "id": "urban-river",
      "title": "Urban-River Intersections: Implications for Sustainable Development",
      "kind": "Map / spatial analysis",
      "category": "Fieldwork & maps",
      "year": "M.A. coursework",
      "topics": [
        "GIS",
        "Urban systems",
        "Environment"
      ],
      "summary": "This GIS mapping exercise identifies spatial intersections between major urban areas and river corridors in India. Using QGIS and Natural Earth geographic data, it constructs ten-kilometre buffers around river networks and overlays them with urban areas to visualise locations of potential proximity and overlap. The resulting map provides a preliminary spatial screening tool for examining urban-river relationships. It does not measure water quality or establish environmental impacts, but identifies locations where more detailed analysis of land use, flood exposure and riverine ecosystems may be warranted.",
      "methods": [
        "QGIS",
        "Buffer analysis",
        "Thematic mapping"
      ],
      "note": "The CV documents the map project but the original map asset is not included in this first site build. Add the export or project file to display it accurately.",
