      "summary": "This essay examines digital surveillance as a relationship between information, behavioural regulation and institutional power. Drawing on Michel Foucault's account of disciplinary power and Shoshana Zuboff's concept of surveillance capitalism, it considers how platforms and corporations collect, analyse and monetise behavioural data. Examples involving targeted advertising, data breaches and political profiling illustrate the asymmetry between organisations that control information and individuals who generate it. The essay argues that digital infrastructures can reproduce concentrated forms of power even where technological access appears decentralised, raising questions of privacy, consent and the public ownership of knowledge.",
