      "id": "ai-bias",
      "title": "From Data to Decision: Unveiling the Human Biases in AI and Algorithms",
      "kind": "Essay",
      "category": "Essays",
      "year": "",
      "topics": [
        "Technology, politics & society",
        "AI governance"
      ],
      "summary": "This essay examines the claim that algorithmic decision-making is objective, drawing on scholarship concerning public relevance algorithms and the social construction of digital information. It analyses how data selection, classification, relevance ranking and predictive profiling embed human judgments within apparently automated processes. The discussion considers algorithmic visibility, filter bubbles and the implications of opaque ranking systems for public discourse and individual autonomy. It argues that automation does not eliminate bias but may relocate it to the design and governance of data-driven systems, where its operation becomes less visible to users.",
      "methods": [
        "Research-based writing",
        "Technology and society"
      ],
      "note": "Add the original essay to display its complete text and exact formatting.",
